INSERT INTO payment (
payment_type, amount, status, method, idempotency_key, order_id,
paid_at, created_at, updated_at,
fair_id, business_id, payer_user_id, reservation_id, application_id
) VALUES (
#{paymentType}, #{amount}, #{status}, #{method}, #{idempotencyKey}, #{orderId},
#{paidAt}, #{createdAt}, #{updatedAt},
#{fairId}, #{businessId}, #{payerUserId}, #{reservationId}, #{applicationId}
)

mapper.update:
UPDATE payment
SET status = 'PROCESSING',
updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}
AND status = 'PENDING'

UPDATE payment
SET status = 'FAILED',
updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}
AND status = 'PROCESSING'

UPDATE payment
SET status = 'CANCELED',
updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}
AND status = 'PENDING'

UPDATE payment
SET status = 'EXPIRED',
updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}
AND status = 'PENDING'
